41	const PROCESSING_FEE = 5;
42	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
43	const CURSE_SURCHARGE = 0.5;
44	
45	const BASE_PREMIUMS: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	};
53	
54	/** Premiums round up: fractions of a Gold piece go to the MHPCO, never the customer. */
55	const roundPremiumInMHPCOFavour = (amount: number): number => Math.ceil(amount);
56	
57	const COMPONENT_BLOCK_SIZE = 3;
58	const COMPONENT_BLOCK_PREMIUM = 60;
59	
60	const countsByType = (items: Item[]): Map<string, number> =>
61	  items.reduce(
62	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
63	    new Map<string, number>(),
64	  );
65	
66	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
67	
68	/** Exactly three alike components form a building block, priced at a flat rate. */
69	const basePremiumForAlikeItems = (type: string, count: number): number =>
70	  COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE
71	    ? COMPONENT_BLOCK_PREMIUM
72	    : count * BASE_PREMIUMS[type];
73	
74	const policyBasePremium = (items: Item[]): number =>
75	  [...countsByType(items)].reduce(
76	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
77	    0,
78	  );
79	
80	/** Policy-wide modifiers are rates on the policy base premium, not on each other. */
81	const applyRate = (basePremium: number, rate: number): number => basePremium * rate;
82	
83	/** Item-specific surcharges are rates on the affected item's own base premium. */
84	const itemSurcharges = (items: Item[]): number =>
85	  items.reduce(
86	    (total, item) =>
87	      total + (item.cursed ? applyRate(BASE_PREMIUMS[item.type], CURSE_SURCHARGE) : 0),
88	    0,
89	  );
90	
91	const quote = (step: QuoteStep): StepResult => {
92	  const base = policyBasePremium(step.items);
93	  return {
94	    premium: roundPremiumInMHPCOFavour(
95	      base +
96	        itemSurcharges(step.items) +
97	        applyRate(base, INITIAL_ASSESSMENT_SURCHARGE) +
98	        PROCESSING_FEE,
99	    ),
100	  };
101	};
102	
103	const runStep = (step: Step): StepResult => {
104	  if (step.op === "quote") return quote(step);
105	  throw new Error(`Unsupported step: ${step.op}`);
106	};
107	
108	export const runScenario = (scenario: Scenario): ScenarioResult => ({
109	  results: scenario.steps.map(runStep),
110	});
