/** Modifiers are rates on a base premium, not on each other. Returns the surcharge alone. */
const rateOf = (basePremium: number, rate: number): number => basePremium * rate;

/** Item-specific surcharge rates stack additively on the item's own base premium. */
const surchargeRateFor = (item: Item): number => (item.cursed ? CURSE_SURCHARGE : 0);

/** Item-specific surcharges are rates on the affected item's own base premium. */
const itemSurcharges = (items: Item[]): number =>
  items.reduce(
    (total, item) => total + rateOf(BASE_PREMIUMS[item.type], surchargeRateFor(item)),
    0,
  );
